<script setup>
import { computed, onBeforeUnmount, onMounted, ref } from 'vue'
import { useRoute, useRouter } from 'vue-router'
import { demoDreams, downloadText, today, useDreamJourney } from '../composables/useDreamJourney'
import { useJourneyUi } from '../composables/useJourneyUi'
import { dreamReady, dreamError, syncDreamAccount, retryDreamAccount } from '../dream-account'
const route=useRoute(),router=useRouter(), {snapshots,creations,refresh,commit}=useDreamJourney(),{toast,notify,save,copy}=useJourneyUi()
const tab=ref('梦境绘图'), tabs=['梦境绘图','作品整理','故事续写','海报与分享'], sourceId=ref(''), title=ref(''), text=ref(''), image=ref(''), prompt=ref(''), result=ref(''), busy=ref(false), error=ref(''), listening=ref(false), poster=ref(''), edited=ref(false)
const current=computed(()=>snapshots.value.find(s=>String(s.id)===sourceId.value)), draftLength=computed(()=>text.value.replace(/\s/g,'').length)
const sourcePicker=ref(null)
function chooseSnapshot(snapshot){sourceId.value=String(snapshot.id);loadSnapshot();closeSourcePicker()}
function closeSourcePicker(){if(sourcePicker.value){sourcePicker.value.open=false;sourcePicker.value.querySelector('summary')?.focus()}}
let controller, recognition, createdPoster
function loadSnapshot(){const s=current.value;if(!s)return;title.value=s.title||'昨夜的一场梦';text.value=s.signal||s.coreReport?.inner||'';image.value=s.image||'';prompt.value=s.imagePrompt||s.signal||'';result.value='';poster.value='';error.value='';edited.value=false;notify('这幅快照已放到工作台，原记录保持完整')}
function loadDemo(){closeSourcePicker();poster.value='';error.value='';edited.value=false;const s=demoDreams[0];sourceId.value='';title.value=s.title;text.value=s.signal;image.value=s.image;prompt.value='云雾中的长阶梯，尽头有一扇温暖发光的门，米白与淡紫色，宁静朦胧';result.value='';notify('已放入示例素材，保存后才会进入你的梦库')}
async function request(task){
 if(busy.value)return
 if(!(task==='image'?prompt.value:text.value).trim())return notify(task==='image'?'先描述想看见的画面':'先留下梦境片段，或从梦库带入一幅快照')
 busy.value=true;error.value='';controller=new AbortController();const timeout=setTimeout(()=>controller.abort(),task==='image'?130000:85000)
 try{const response=await fetch(task==='image'?'/api/images/generate':'/api/dream-studio/create',{method:'POST',headers:{'Content-Type':'application/json'},signal:controller.signal,body:JSON.stringify(task==='image'?{prompt:prompt.value}:{task,text:text.value,style:'温柔、保留原有梦境氛围'})});const data=await response.json();if(!response.ok)throw new Error(typeof data.detail==='string'?data.detail:'创作未完成，请检查内容后重试');if(task==='image'){image.value=await compress(data.image);poster.value='';notify('AI 画面已生成，保存后会出现在梦库')}else{result.value=data.text;edited.value=false;notify(task==='continue'?'虚构续写已完成，与你的原始梦境分开保存':'素材已整理，请核对后保存')}}catch(e){error.value=e.name==='AbortError'?'创作已停止或等待超时，可重新尝试。':e.message}finally{clearTimeout(timeout);busy.value=false}
}
function compress(src){return new Promise((resolve,reject)=>{const img=new Image();img.onload=()=>{const c=document.createElement('canvas');const r=Math.min(1,960/Math.max(img.width,img.height));c.width=Math.round(img.width*r);c.height=Math.round(img.height*r);c.getContext('2d').drawImage(img,0,0,c.width,c.height);resolve(c.toDataURL('image/jpeg',.83))};img.onerror=()=>reject(new Error('图片无法读取'));img.src=src})}
async function upload(e){const f=e.target.files?.[0];if(!f)return;if(!f.type.startsWith('image/')||f.size>8*1024*1024)return notify('请选择 8MB 以内的图片');try{const src=await new Promise((r,j)=>{const reader=new FileReader();reader.onload=()=>r(reader.result);reader.onerror=j;reader.readAsDataURL(f)});image.value=await compress(src);poster.value='';notify('图片已放到工作台')}catch{notify('未能读取图片，请重新选择')}}
async function saveWork(){if(!text.value.trim()&&!image.value&&!result.value.trim())return notify('先留下一句信号或一幅画面');const work={id:Date.now(),date:today(),title:title.value.trim()||'一束意识微光',signal:result.value.trim()||text.value.trim(),image:image.value,feeling:current.value?.feeling||'意识碎片',motif:current.value?.motif||'创作',kind:'studio',sourceId:sourceId.value||null,creationType:tab.value==='故事续写'?'虚构续写':tab.value,locked:false};if(await save(commit,'snapshots',[work,...snapshots.value],'作品已作为新快照存入梦库，原快照不会被覆盖'))await save(commit,'creations',[{...work,image:undefined},...creations.value]);}
function startVoice(){const Speech=window.SpeechRecognition||window.webkitSpeechRecognition;if(!Speech)return notify('当前浏览器不支持语音转文字，可以直接输入，或使用系统键盘听写');if(listening.value){recognition?.stop();return}recognition=new Speech();recognition.lang='zh-CN';recognition.interimResults=false;recognition.onresult=e=>{text.value+=(text.value?'，':'')+e.results[0][0].transcript;notify('语音已转为文字，保存前可修改')};recognition.onerror=()=>{listening.value=false;notify('没有获得可用语音，请检查麦克风权限或改用文字输入')};recognition.onend=()=>listening.value=false;try{recognition.start();listening.value=true}catch{notify('麦克风暂时无法开启')}}
function lines(ctx,content,x,y,width,maxLines=8){let line='',count=0;for(const char of content){if(char==='\n'||ctx.measureText(line+char).width>width){ctx.fillText(line,x,y);y+=36;line=char==='\n'?'':char;if(++count>=maxLines)return y}else line+=char}if(line)ctx.fillText(line,x,y);return y+36}
async function makePoster(){try{await document.fonts.ready;const canvas=document.createElement('canvas');canvas.width=1000;canvas.height=1400;const ctx=canvas.getContext('2d');ctx.fillStyle='#F5F1EA';ctx.fillRect(0,0,1000,1400);ctx.save();ctx.translate(500,460);ctx.rotate(-.025);ctx.fillStyle='#fffdfa';ctx.shadowColor='#64516a20';ctx.shadowBlur=30;ctx.fillRect(-420,-370,840,820);ctx.shadowBlur=0;if(image.value){const picture=await new Promise((r,j)=>{const im=new Image();im.onload=()=>r(im);im.onerror=j;im.src=image.value});const ratio=Math.max(780/picture.width,650/picture.height);ctx.save();ctx.beginPath();ctx.rect(-390,-340,780,650);ctx.clip();ctx.drawImage(picture,-390+(780-picture.width*ratio)/2,-340+(650-picture.height*ratio)/2,picture.width*ratio,picture.height*ratio);ctx.restore()}else{ctx.fillStyle='#e8e2ef';ctx.fillRect(-390,-340,780,650);ctx.fillStyle='#7a698e';ctx.font='36px serif';ctx.fillText('昨夜，有一束微光留下',-290,-5)}ctx.fillStyle='#685775';ctx.font='32px serif';lines(ctx,title.value||'一束意识微光',-365,370,720,1);ctx.restore();ctx.fillStyle='#61566b';ctx.font='25px sans-serif';lines(ctx,(result.value||text.value||'把梦轻轻留下。').slice(0,220),100,990,800,7);ctx.font='21px sans-serif';ctx.fillStyle='#8d8096';ctx.fillText('花屿星 · '+today()+' · '+(tab.value==='故事续写'?'虚构创作':'意识快照'),100,1320);poster.value=canvas.toDataURL('image/png');createdPoster=canvas;notify('拍立得分享图已生成，可预览和下载')}catch{notify('海报生成失败，请重新选择图片再试')}}
function downloadImage(src,name){if(!src)return notify('先生成或上传一幅画面');const a=document.createElement('a');a.href=src;a.download=name;a.click();notify('已发起图片下载')}
async function share(){if(!poster.value)await makePoster();if(!poster.value)return;try{if(navigator.canShare&&navigator.share){const blob=await new Promise(r=>createdPoster.toBlob(r,'image/png'));const file=new File([blob],'花屿星-分享海报.png',{type:'image/png'});if(navigator.canShare({files:[file]})){await navigator.share({files:[file],title:title.value||'花屿星意识快照'});return}}downloadImage(poster.value,'花屿星-分享海报.png');notify('当前浏览器不支持系统分享，海报已下载，可自行发送给朋友')}catch(e){if(e.name!=='AbortError')notify('分享未完成，可改用下载海报')}}
onMounted(async()=>{await syncDreamAccount();refresh();if(route.query.snapshot){sourceId.value=String(route.query.snapshot);if(current.value)loadSnapshot();else notify('这幅快照暂未找到，可从梦库重新选择')}})
onBeforeUnmount(()=>{controller?.abort();recognition?.abort()})
</script>
<template>
<div class="journey">
 <p class="j-notice"><span class="j-dot"></span>创作从一场梦出发。整理与续写调用千问；画面生成沿用现有图像服务。</p>
 <div class="j-tabs" role="tablist" aria-label="创作类型"><button v-for="t in tabs" :key="t" role="tab" :aria-selected="tab===t" :class="{'j-selected':tab===t}" :disabled="busy" @click="tab=t;error='';result='';poster=''">{{t}}</button></div>
 <div class="j-wide-grid">
  <aside class="j-panel j-stack"><h2>梦境素材台</h2><div class="snapshot-source"><span id="snapshot-source-label">从我的梦库带入</span>
   <details ref="sourcePicker" class="snapshot-picker" @keydown.esc.prevent="closeSourcePicker">
    <summary aria-labelledby="snapshot-source-label snapshot-source-value"><span id="snapshot-source-value">{{current?.title || '选择一幅快照'}}</span><svg viewBox="0 0 20 20" aria-hidden="true"><path d="m5 8 5 5 5-5"/></svg></summary>
    <div class="snapshot-options" aria-label="梦库快照">
     <p v-if="!dreamReady" role="status">正在接回你的梦库…</p>
     <div v-else-if="dreamError" class="snapshot-empty"><p>梦库暂时未能载入，请重试。</p><button type="button" @click="retryDreamAccount">重新载入</button></div>
     <template v-else-if="snapshots.length"><button v-for="s in snapshots" :key="s.id" type="button" :disabled="busy" :aria-pressed="sourceId===String(s.id)" @click="chooseSnapshot(s)"><img v-if="s.image" :src="s.image" alt="" loading="lazy"><span v-else class="snapshot-placeholder" aria-hidden="true">✦</span><span class="snapshot-option-copy"><strong>{{s.title || '未命名快照'}}</strong><small>{{s.date || '日期未留下'}} · {{s.feeling || '意识碎片'}}</small></span><span v-if="sourceId===String(s.id)" aria-hidden="true">✓</span></button></template>
     <div v-else class="snapshot-empty"><p>梦库还没有留下快照。先记一场梦，或用示例试试创作。</p><button type="button" :disabled="busy" @click="loadDemo">体验示例素材</button></div>
    </div>
   </details><small>选择后带入画面和片段，原始快照保持完整。</small>
  </div><button :disabled="busy" @click="loadDemo">放入一份示例素材</button><label>作品标题<input v-model="title" maxlength="60" placeholder="给这一束微光起个名字"></label><label>残留的梦境片段<textarea v-model="text" rows="5" maxlength="6000" placeholder="一句话也可以，例如：我一直走在云里的阶梯上…"></textarea></label><div class="j-between"><small>{{draftLength}} 字</small><button class="j-small-action" :aria-pressed="listening" @click="startVoice">{{listening?'停止听写':'语音留下一句'}}</button></div><small>语音听写使用浏览器能力，可能需要浏览器提供的联网服务；不支持时可直接输入。</small><div class="j-row"><span class="j-tag">{{current?.date||today()}}</span><span class="j-tag blue">{{current?.feeling||'自由创作'}}</span></div><p class="j-help">只整理素材与感受，不为梦境赋予象征含义，也不把续写当作真实记忆。</p></aside>
  <section class="j-stack">
   <div v-if="tab==='梦境绘图'" class="j-panel"><h2>让画面，慢慢浮现</h2><p class="j-muted">描述梦里的光线、场景和颜色。</p><label>画面描述<textarea v-model="prompt" rows="3" maxlength="1000" placeholder="穿过云层的阶梯，尽头有一扇温暖发光的门…"></textarea></label><div class="j-row j-section-gap"><button class="j-primary" :disabled="busy" @click="request('image')">{{busy?'正在汇聚画面…':'生成梦境图片'}}</button><button v-if="image" @click="downloadImage(image,'花屿星-梦境画面.png')">保存图片</button></div><figure v-if="image" class="studio-picture"><img :src="image" alt="梦境画面" class="j-art"><figcaption><small>{{title||'未命名画面'}} · {{today()}}</small></figcaption></figure><div v-else class="j-empty j-section-gap"><img src="/dream-rooms/entrance.png" alt="梦境入口插画"><p>还没浮现的画面，先从一句描述开始。</p></div></div>
   <div v-else-if="tab==='作品整理'||tab==='故事续写'" class="j-panel"><h2>{{tab==='作品整理'?'把散落的片段，轻轻整理':'让故事，往前走一小段'}}</h2><p>{{tab==='作品整理'?'按标题、摘要、正文整理原素材，生成后仍可编辑。':'续写将明确标为虚构创作，原快照不受影响。'}}</p><div class="j-row"><button class="j-primary" :disabled="busy" @click="request(tab==='作品整理'?'organize':'continue')">{{busy?'千问正在创作…':tab==='作品整理'?'AI 整理素材':'AI 续写故事'}}</button><button @click="result=text;edited=true">从原文手动编辑</button></div><label v-if="result" class="j-section-gap">{{edited?'你的编辑稿':'AI 草稿 · 请核对后保存'}}<textarea v-model="result" rows="13" maxlength="12000" @input="edited=true"></textarea></label><div v-if="result" class="j-row j-section-gap"><button @click="copy(result)">复制全文</button><button @click="downloadText((title||'梦境作品')+'.txt',result)">导出文字</button></div></div>
   <div v-else class="j-panel"><h2>把一场梦，留成一张拍立得</h2><p class="j-muted">用素材台的标题、画面和文字生成分享海报。</p><div class="j-row"><button class="j-primary" @click="makePoster">生成分享海报</button><button v-if="poster" @click="downloadImage(poster,'花屿星-分享海报.png')">下载海报</button><button v-if="poster" @click="share">分享给朋友</button></div><img v-if="poster" :src="poster" class="studio-poster" alt="花屿星拍立得分享海报"><div v-else class="j-empty j-section-gap"><p>由你决定，把哪一束微光带给别人。</p></div></div>
   <div v-if="busy" class="j-panel" role="status">创作需要一点时间，请留在这一页。<button class="j-small-action" @click="controller?.abort()">停止等待</button></div><p v-if="error" class="j-error" role="alert">{{error}}</p>
   <div class="j-panel j-between"><div><h3>留在你的梦库</h3><small>作为新快照保存，不覆盖原始内容。</small></div><button class="j-primary" :disabled="busy" @click="saveWork">保存本次作品</button></div>
   <div v-if="creations.length" class="j-panel"><h3>最近的创作回响</h3><p v-for="w in creations.slice(0,3)" :key="w.id"><small>{{w.date}} · {{w.creationType}}</small><br>{{w.title}}</p></div>
  </section>
 </div><div v-if="toast" class="j-toast" role="status">{{toast}}</div>
</div>
</template>
<style scoped>.studio-picture{margin:24px 0 0}.studio-picture figcaption{padding:9px 0}.studio-poster{width:min(100%,450px);margin:25px auto 0;display:block;border-radius:12px;border:1px solid #e5e0ed}.studio-picture img{max-height:500px;object-fit:contain;background:#f5f1f8}</style>

<style scoped>
.snapshot-source{display:grid;gap:8px;min-width:0}.snapshot-picker{position:relative;min-width:0}.snapshot-picker summary{display:flex;align-items:center;justify-content:space-between;gap:12px;min-height:48px;padding:11px 14px;border:1px solid var(--j-line);border-radius:14px;background:#fffefc;cursor:pointer;list-style:none}.snapshot-picker summary::-webkit-details-marker{display:none}.snapshot-picker summary span{overflow:hidden;text-overflow:ellipsis;white-space:nowrap}.snapshot-picker summary svg{width:18px;height:18px;flex:none;fill:none;stroke:currentColor;stroke-width:1.5}.snapshot-picker[open] summary{border-color:#a69ab8;background:#f9f6fc}.snapshot-options{position:absolute;top:calc(100% + 8px);left:0;right:0;z-index:15;max-height:320px;overflow:auto;overscroll-behavior:contain;padding:8px;background:#fffdfa;border:1px solid #ded5e8;border-radius:16px;box-shadow:0 10px 28px #514c6514}.snapshot-options>button{display:flex;width:100%;justify-content:flex-start;gap:10px;text-align:left;border:0;background:transparent;padding:10px;border-radius:10px}.snapshot-options>button[aria-pressed=true]{background:#f0eaf6}.snapshot-options img,.snapshot-placeholder{width:42px;height:48px;border-radius:8px;object-fit:cover;flex:none}.snapshot-placeholder{display:grid;place-items:center;background:#eeebf6;color:#9284a9}.snapshot-option-copy{display:grid;gap:3px;min-width:0;flex:1}.snapshot-option-copy strong{font-size:14px;font-weight:500;overflow-wrap:anywhere}.snapshot-option-copy small{font-size:12px}.snapshot-empty{padding:10px;font-size:13px}.snapshot-empty p{margin:0 0 12px}.snapshot-empty button{font-size:13px}.snapshot-options>p{padding:10px;font-size:13px}
</style>
